def domain_counts() -> dict[str, int]:
    """Return the number of users per lowercase email domain."""
    counts: dict[str, int] = {}
    for email in store.all_emails():
        _, separator, domain = email.rpartition("@")
        if separator and domain:
            key = domain.lower()
            counts[key] = counts.get(key, 0) + 1
    return counts

